'use strict';
// email-semana-v4.js — Plantilla REAL del email de la semana, diseño v4 aprobado 30/10.
//
// Builder puro: no toca DB ni envía nada. Lo usa sendWeekReady (notify-email.js)
// cuando el autopilot deja la semana programada.
//
// Reglas duras de la muestra v4:
//  - CERO <img> externos: el único <img> es el avatar canónico como data URI,
//    círculo con borde #FEC14D (la cabecera anterior usaba una URL externa).
//  - Textos completos sin '…': el pie completo va en cada tarjeta (el preview
//    viejo cortaba a 180 caracteres).
//  - Fecha real por posteo, en el timezone del usuario.
//  - Cada tarjeta clickeable a su deep link #/app/post/:id.
//  - Botón "Aprobar semana" + cierre "Aprobar los 8 posteos".
//  - Tirita Lun–Lun con punto por día.
//  - La semana es Lun–Lun = 8 posteos. Si llegan menos de 8 (semana parcial),
//    el conteo, el título y la tirita usan el número real: la verdad sobre el copy.
//  - La muestra incluía un div "Asunto: ..." como artefacto del mock: en el
//    email real el asunto va en el campo subject, no en el cuerpo (no se incluye).
//  - EN: traducción directa del copy aprobado (misma práctica que la paridad v373);
//    queda pendiente la revisión de Valentino del copy EN.
//
// El gancho visual de cada tarjeta es la primera frase del pie real (el posteo
// no tiene campo titular en DB); si el pie está vacío, usa el tipo o "Posteo".

const AVATAR_DATA_URI = 'data:image/png;base64,';

function esc(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Misma regla que approval.js parseUtc: 'YYYY-MM-DD HH:MM:SS' de SQLite se
// marca como UTC explícita (new Date la tomaría como hora local).
function parseUtc(iso) {
  const s = String(iso || '').trim();
  if (!s) return null;
  const d = new Date(/[zZ]$|[+-]\d{2}:?\d{2}$/.test(s) ? s : s.replace(' ', 'T') + 'Z');
  return Number.isNaN(d.getTime()) ? null : d;
}

// Fecha real del posteo en el tz del usuario (el día y la hora salen de
// formatToParts con ese tz: usar getDay() del Date UTC estaría mal cuando
// el tz cruza de día, p.ej. 01:00 UTC = 22:00 del día anterior en BA).
// ES: LUN 2 NOV · 19:00 — EN: MON NOV 2 · 7:00 PM.
function fmtPostDate(iso, tz, lang) {
  const d = parseUtc(iso);
  if (!d) return null;
  const en = lang === 'en';
  try {
    const parts = new Intl.DateTimeFormat(en ? 'en-US' : 'es-AR', {
      weekday: 'short', day: 'numeric', month: 'short',
      hour: '2-digit', minute: '2-digit', hour12: en, timeZone: tz,
    }).formatToParts(d);
    const get = (t) => (parts.find((p) => p.type === t) || {}).value || '';
    const wd = get('weekday').replace(/\.$/, '').toUpperCase();
    const mo = get('month').replace(/\.$/, '').toUpperCase();
    const dom = get('day');
    const hh = get('hour');
    const mm = get('minute');
    const ap = get('dayPeriod');
    if (!wd || !dom || !mo || !hh) return null;
    if (en) return { dow: wd, dom, mon: mo, hm: `${Number(hh)}:${mm} ${ap}`.trim() };
    return { dow: wd, dom, mon: mo, hm: `${hh}:${mm}` };
  } catch (e) {
    return null;
  }
}

// Primera frase del pie (con su puntuación), capada a 80 caracteres por
// borde de palabra. Es solo el gancho visual: el pie completo va debajo.
function hookOf(caption, tipo, lang) {
  const c = String(caption || '').trim();
  if (c) {
    const m = c.match(/^(.{1,200}?[.!?])(\s|$)/);
    let h = m ? m[1].trim() : c;
    if (h.length > 80) {
      const cut = h.slice(0, 80);
      const sp = cut.lastIndexOf(' ');
      h = (sp > 40 ? cut.slice(0, sp) : cut).trim();
    }
    return h;
  }
  const t = String(tipo || '').trim();
  if (t) return t;
  return lang === 'en' ? 'Post' : 'Posteo';
}

const CSS = `
  body { margin: 0; background: #e8f0f6; font-family: -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; color: #0A1E33; }
  .wrap { max-width: 600px; margin: 0 auto; background: #f2f7fb; padding-bottom: 32px; }
  .header { background: #2793C8; color: #fff; padding: 18px 28px; display: flex; align-items: center; gap: 14px; }
  .avatar { width: 52px; height: 52px; border-radius: 50%; object-fit: cover; border: 2px solid #FEC14D; background: #fff; flex-shrink: 0; }
  .header .logo { font-size: 26px; font-weight: 800; letter-spacing: -0.5px; }
  .header .logo span { color: #FEC14D; }
  .header .tag { font-size: 13px; opacity: 0.9; margin-top: 2px; }
  .hero { padding: 28px 28px 8px; }
  .hero h1 { font-size: 30px; line-height: 1.15; margin: 0 0 10px; color: #0A1E33; }
  .hero p { font-size: 16px; line-height: 1.5; margin: 0 0 18px; color: #33475e; }
  .btn { display: inline-block; background: #FEC14D; color: #0A1E33; font-weight: 700; font-size: 16px; text-decoration: none; padding: 13px 26px; border-radius: 999px; }
  .hint { font-size: 13px; color: #5b7186; margin: 14px 0 0; }
  .auto { background: #fff7e0; border: 1px solid #FEC14D; border-radius: 12px; margin: 16px 0 0; padding: 12px 18px; font-size: 14px; line-height: 1.5; text-align: center; }
  a.card-link { display: block; text-decoration: none; color: inherit; }
  .card { background: #fff; border: 1px solid #dbe7ef; border-radius: 16px; margin: 20px 20px 0; overflow: hidden; }
  .visual { background: linear-gradient(135deg, #0A1E33 0%, #2793C8 100%); color: #fff; padding: 26px 24px; }
  .visual .hook { font-size: 23px; font-weight: 800; line-height: 1.2; margin: 0; }
  .visual .mark { font-size: 12px; letter-spacing: 1px; text-transform: uppercase; opacity: 0.75; margin-top: 10px; }
  .body { padding: 16px 22px 18px; }
  .when { color: #2793C8; font-weight: 800; font-size: 14px; letter-spacing: 0.5px; margin: 0 0 8px; }
  .caption { font-size: 15px; line-height: 1.55; margin: 0; color: #0A1E33; }
  .open { font-size: 13px; color: #2793C8; font-weight: 600; margin: 10px 0 0; }
  .strip-title { text-align: center; font-size: 13px; color: #5b7186; margin: 22px 0 0; }
  .strip { display: flex; background: #fff; border: 1px solid #dbe7ef; border-radius: 16px; margin: 10px 20px 0; padding: 12px 8px; }
  .day { flex: 1; text-align: center; font-size: 11px; color: #5b7186; }
  .day strong { display: block; font-size: 17px; color: #0A1E33; }
  .day i { font-style: normal; color: #2793C8; font-size: 14px; }
  .closing { text-align: center; padding: 26px 20px 0; }
  .closing p { font-size: 15px; line-height: 1.5; color: #33475e; margin: 0 0 14px; }
  .footer { padding: 26px 28px 0; font-size: 13px; line-height: 1.6; color: #5b7186; text-align: center; }
  .footer a { color: #2793C8; text-decoration: none; font-weight: 600; }
`;

// posts: [{ id, caption, tipo, scheduled_at }] ordenados por scheduled_at.
// approveUrl: un toque aprueba la semana (publish firmado, como el preview).
// baseUrl: origen del deep link #/app/post/:id y de "Abrir Posty".
// tz: timezone del usuario (default America/Argentina/Buenos_Aires).
function buildWeekEmailV4(opts) {
  const o = opts || {};
  const biz = String(o.biz || '').slice(0, 80) || 'tu negocio';
  const en = o.lang === 'en';
  const base = String(o.baseUrl || 'https://postycommunitymanager.com').replace(/\/$/, '');
  const tz = o.tz || 'America/Argentina/Buenos_Aires';
  const approve = String(o.approveUrl || `${base}/#/app/schedule`);
  const posts = (Array.isArray(o.posts) ? o.posts : []).map((p) => {
    const f = fmtPostDate(p.scheduled_at, tz, en ? 'en' : 'es');
    return { id: p.id, caption: String(p.caption || ''), hook: hookOf(p.caption, p.tipo, en ? 'en' : 'es'), f };
  });
  const n = posts.length;

  // Hora uniforme (todas las tarjetas a la misma hora): el copy aprobado
  // "uno por día, a las 19:00" sale exacto. Si difieren, el hero y la caja
  // dicen "uno por día" sin hora: la verdad sobre el copy.
  const hours = posts.map((p) => (p.f ? p.f.hm : '')).filter(Boolean);
  const uniformHour = hours.length === n && n > 0 && hours.every((h) => h === hours[0]) ? hours[0] : '';

  const subject = en ? `Your week is ready: ${n} posts` : `Tu semana está lista: ${n} posteos`;
  const title = en ? `${esc(biz)}'s week is ready` : `La semana de ${esc(biz)} está lista`;
  const heroSub = en
    ? `<strong>${n} posts</strong> · one a day${uniformHour ? `, at ${uniformHour}` : ''}.<br>Tap any post to see it in the app.`
    : `<strong>${n} posteos</strong> · uno por día${uniformHour ? `, a las ${uniformHour}` : ''}.<br>Tocá cualquier posteo para verlo en la app.`;
  const approveLabel = en ? 'Approve week' : 'Aprobar semana';
  const hint = en
    ? 'Want to change something? Reply to this email or tap the post in the app.'
    : 'Si querés cambiar algo, respondé este email o tocá el posteo en tu Bandeja.';
  const autoBox = en
    ? `✦ If you don't tell me otherwise, all ${n} go out as-is${uniformHour ? `, one a day at ${uniformHour}` : ', one a day'}.`
    : `✦ Si no me decís nada, los ${n} salen así${uniformHour ? `, uno por día a las ${uniformHour}` : ', uno por día'}.`;
  const stripTitle = en ? 'Your week at a glance' : 'Tu semana de un vistazo';
  const strip = posts.map((p) => {
    const f = p.f || {};
    return `<div class="day">${esc(f.dow || '')}<strong>${esc(f.dom || '')}</strong><i>●</i></div>`;
  }).join('');
  const cards = posts.map((p) => {
    const f = p.f || {};
    const when = en
      ? `${esc(f.dow || '')} ${esc(f.mon || '')} ${esc(f.dom || '')} · ${esc(f.hm || '')}`
      : `${esc(f.dow || '')} ${esc(f.dom || '')} ${esc(f.mon || '')} · ${esc(f.hm || '')}`;
    const link = `${base}/#/app/post/${encodeURIComponent(p.id)}`;
    return `<a class="card-link" href="${esc(link)}">
    <div class="card">
      <div class="visual"><p class="hook">${esc(p.hook)}</p><div class="mark">Posty ✦</div></div>
      <div class="body">
        <p class="when">${when}</p>
        <p class="caption">${esc(p.caption)}</p>
        <p class="open">${en ? 'See in the app →' : 'Ver en la app →'}</p>
      </div>
    </div>
  </a>`;
  }).join('\n  ');
  const closingQ = en ? 'Like the week as-is?' : '¿Te gusta la semana así?';
  const closingBtn = en ? `Approve all ${n} posts` : `Aprobar los ${n} posteos`;
  const foot = en
    ? `Posty — your community manager<br>
    <a href="${esc(base)}">Open Posty</a> · Reply to this email if you want to change something<br>
    If you don't want these notices, tell me in the chat.`
    : `Posty — tu community manager<br>
    <a href="${esc(base)}">Abrir Posty</a> · Respondé este email si querés cambiar algo<br>
    Si no querés recibir estos avisos, decímelo en el chat.`;

  const html = `<!DOCTYPE html>
<html lang="${en ? 'en' : 'es'}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(subject)} — Posty</title>
<style>${CSS}</style>
</head>
<body>
<div class="wrap">
  <div class="header">
    <img class="avatar" src="${AVATAR_DATA_URI}" alt="Posty" width="52" height="52">
    <div>
      <div class="logo">Posty <span>✦</span></div>
      <div class="tag">${en ? 'your community manager' : 'tu community manager'}</div>
    </div>
  </div>

  <div class="hero">
    <h1>${title}</h1>
    <p>${heroSub}</p>
    <a class="btn" href="${esc(approve)}">${approveLabel}</a>
    <p class="hint">${hint}</p>
    <div class="auto">${autoBox}</div>
  </div>

  <div class="strip-title">${stripTitle}</div>
  <div class="strip">
    ${strip}
  </div>

  ${cards}

  <div class="closing">
    <p>${closingQ}</p>
    <a class="btn" href="${esc(approve)}">${closingBtn}</a>
  </div>

  <div class="footer">
    <p>${foot}</p>
  </div>

</div>
</body>
</html>`;
  return { subject, html };
}

module.exports = { buildWeekEmailV4, _internal: { fmtPostDate, hookOf, esc } };
